"use client"

import { cn } from "@/lib/utils"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Card, CardContent, CardFooter, CardHeader } from "@/components/ui/card"
import {
  LiveIndicator,
  type LiveIndicatorStatus,
} from "@/registry/mrdoge-ui/live-indicator/live-indicator"
import {
  OddsSelector,
  type OddsOption,
} from "@/registry/mrdoge-ui/odds-selector/odds-selector"

export interface EventCardTeam {
  name: string
  logoUrl?: string
}

export interface EventCardProps {
  competition: string
  status: LiveIndicatorStatus
  kickoff?: Date | string
  elapsed?: string
  home: EventCardTeam
  away: EventCardTeam
  homeScore?: number
  awayScore?: number
  odds: OddsOption[]
  selectedOddsId?: string
  onSelectOdds?: (id: string) => void
  className?: string
}

function TeamRow({
  team,
  score,
  showScore,
}: {
  team: EventCardTeam
  score?: number
  showScore: boolean
}) {
  return (
    <div className="flex items-center justify-between">
      <div className="flex min-w-0 items-center gap-2">
        <Avatar size="sm" className="bg-muted">
          <AvatarImage src={team.logoUrl} alt={team.name} />
          <AvatarFallback>{team.name.slice(0, 2).toUpperCase()}</AvatarFallback>
        </Avatar>
        <span className="truncate text-sm font-medium">{team.name}</span>
      </div>
      {showScore ? (
        <span className="text-sm font-semibold tabular-nums">{score ?? 0}</span>
      ) : null}
    </div>
  )
}

export function EventCard({
  competition,
  status,
  kickoff,
  elapsed,
  home,
  away,
  homeScore,
  awayScore,
  odds,
  selectedOddsId,
  onSelectOdds,
  className,
}: EventCardProps) {
  const showScore = status !== "scheduled"

  return (
    <Card className={cn("w-full max-w-sm", className)}>
      <CardHeader className="flex-row items-center justify-between">
        <span className="truncate text-xs text-muted-foreground">
          {competition}
        </span>
        <LiveIndicator status={status} kickoff={kickoff} elapsed={elapsed} />
      </CardHeader>
      <CardContent className="flex flex-col gap-2">
        <TeamRow team={home} score={homeScore} showScore={showScore} />
        <TeamRow team={away} score={awayScore} showScore={showScore} />
      </CardContent>
      <CardFooter className="border-t bg-transparent pt-4">
        <OddsSelector
          options={odds}
          selectedId={selectedOddsId}
          onSelect={onSelectOdds}
          className="w-full"
        />
      </CardFooter>
    </Card>
  )
}

import { Clock } from "lucide-react"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"

export type LiveIndicatorStatus = "scheduled" | "live" | "finished"

export interface LiveIndicatorProps {
  status: LiveIndicatorStatus
  /** Kickoff time, shown when status is "scheduled". */
  kickoff?: Date | string
  /** Elapsed match clock (e.g. "67'"), shown when status is "live". */
  elapsed?: string
  className?: string
}

function formatKickoff(kickoff: Date | string) {
  const date = typeof kickoff === "string" ? new Date(kickoff) : kickoff
  return date.toLocaleTimeString(undefined, {
    hour: "numeric",
    minute: "2-digit",
  })
}

// Only 3 states are representable here because that's all the underlying
// event data reliably distinguishes — don't add a "postponed"/"delayed"
// variant without a data source that can actually back it.
export function LiveIndicator({
  status,
  kickoff,
  elapsed,
  className,
}: LiveIndicatorProps) {
  if (status === "live") {
    return (
      <Badge
        variant="destructive"
        className={cn("gap-1.5 border-transparent bg-destructive text-destructive-foreground", className)}
      >
        <span className="relative flex size-1.5">
          <span className="absolute inline-flex size-full animate-ping rounded-full bg-destructive-foreground/60" />
          <span className="relative inline-flex size-1.5 rounded-full bg-destructive-foreground" />
        </span>
        {elapsed ?? "LIVE"}
      </Badge>
    )
  }

  if (status === "finished") {
    return (
      <Badge variant="secondary" className={className}>
        Finished
      </Badge>
    )
  }

  return (
    <Badge variant="outline" className={cn("gap-1", className)}>
      <Clock className="size-3" />
      {kickoff ? formatKickoff(kickoff) : "Scheduled"}
    </Badge>
  )
}

"use client"

import type { ComponentType } from "react"
import { Minus, TrendingDown, TrendingUp } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

export type OddsMovement = "up" | "down" | "flat"

export interface OddsOption {
  id: string
  /** Selection label, e.g. "1", "X", "2" or "Home", "Away". */
  label: string
  /** Formatted price, e.g. "1.85". */
  price: string
  movement?: OddsMovement
  suspended?: boolean
}

export interface OddsSelectorProps {
  options: OddsOption[]
  selectedId?: string
  onSelect?: (id: string) => void
  className?: string
}

const movementIcon: Record<OddsMovement, ComponentType<{ className?: string }>> = {
  up: TrendingUp,
  down: TrendingDown,
  flat: Minus,
}

const movementColor: Record<OddsMovement, string> = {
  up: "text-emerald-600 dark:text-emerald-500",
  down: "text-destructive",
  flat: "text-muted-foreground",
}

export function OddsSelector({
  options,
  selectedId,
  onSelect,
  className,
}: OddsSelectorProps) {
  return (
    <div className={cn("grid auto-cols-fr grid-flow-col gap-2", className)}>
      {options.map((option) => {
        const MovementIcon = option.movement
          ? movementIcon[option.movement]
          : null
        const selected = option.id === selectedId

        return (
          <Button
            key={option.id}
            type="button"
            variant={selected ? "default" : "outline"}
            disabled={option.suspended}
            onClick={() => onSelect?.(option.id)}
            className="h-auto flex-col gap-0.5 py-1.5"
          >
            <span className="text-xs font-normal opacity-80">
              {option.label}
            </span>
            <span className="flex items-center gap-1 text-sm font-semibold">
              {option.suspended ? "—" : option.price}
              {MovementIcon && !option.suspended ? (
                <MovementIcon
                  className={cn(
                    "size-3",
                    selected ? "opacity-90" : movementColor[option.movement!]
                  )}
                />
              ) : null}
            </span>
          </Button>
        )
      })}
    </div>
  )
}
